key:=m.rule_profile_key;\n  new.rule_profile_version_id:=m.rule_profile_version_id;\n  new.rule_profile_version:=m.rule_profile_version;\n  new.rule_pack_checksum:=m.rule_pack_checksum;\n  new.rule_pack_snapshot:=m.rule_pack_snapshot;\n  return new;\nend; ","before":"e5ca83ed4de2483c9567026790906de5","canonical_body":"\ndeclare m public.ediel_messages%rowtype;\nbegin\n  select * into m from public.ediel_messages where id=new.ediel_message_id;\n  if not found then raise exception ''ediel_outbox_message_missing'' using errcode=''23503''; end if;\n  if new.company_id is null or m.company_id is null or new.company_id<>m.company_id then\n    raise exception ''ediel_outbox_message_tenant_mismatch'' using errcode=''23514'';\n  end if;\n  if m.direction<>''outbound'' then raise exception ''ediel_outbox_requires_outbound_message'' using errcode=''23514''; end if;\n  if m.message_family in (''PRODAT'',''UTILTS'',''CONTRL'',''APERAK'',''UTILTS_ERR'')\n     and (m.rule_profile_version_id is null or nullif(m.rule_pack_checksum,'''') is null)\n     and not (m.canonical_rule_pack_id is null and m.rule_profile_version_id is null\n       and (m.message_family=''CONTRL''\n        or (m.message_family=''APERAK'' and m.execution_context_snapshot ? ''prodatCommonHeaderNegativeWitnessId''))) then\n    raise exception ''ediel_outbox_rule_pack_snapshot_missing'' using errcode=''23514'';\n  end if;\n  new.rule_profile_key:=m.rule_profile_key;\n  new.rule_profile_version_id:=m.rule_profile_version_id;\n  new.rule_profile_version:=m.rule_profile_version;\n  new.rule_pack_checksum:=m.rule_pack_checksum;\n  new.rule_pack_snapshot:=m.rule_pack_snapshot;\n  return new;\nend; ","canonical_md5":"a218eec9f0ac5e17a1c2cd059e83b6b8","after_body":"\ndeclare m public.ediel_messages%rowtype;\nbegin\n  select * into m from public.ediel_messages where id=new.ediel_message_id;\n  if not found then raise exception ''ediel_outbox_message_missing'' using errcode=''23503''; end if;\n  if new.company_id is null or m.company_id is null or new.company_id<>m.company_id then\n    raise exception ''ediel_outbox_message_tenant_mismatch'' using errcode=''23514'';\n  end if;\n  if m.direction<>''outbound'' then raise exception ''ediel_outbox_requires_outbound_message'' using errcode=''23514''; end if;\n  if m.message_family in (''PRODAT'',''UTILTS'',''CONTRL'',''APERAK'',''UTILTS_ERR'')\n     and (m.rule_profile_version_id is null or nullif(m.rule_pack_checksum,'''') is null)\n     and m.canonical_rule_pack_id is null and m.rule_profile_version_id is null\n     and (m.message_family=''CONTRL''\n       or (m.message_family=''APERAK'' and m.execution_context_snapshot ? ''prodatCommonHeaderNegativeWitnessId'')) then\n    perform public.gridex_require_outbound_reply_basis_v1(m);\n  end if;\n  if m.message_family in (''PRODAT'',''UTILTS'',''CONTRL'',''APERAK'',''UTILTS_ERR'')\n     and (m.rule_profile_version_id is null or nullif(m.rule_pack_checksum,'''') is null)\n     and not (m.canonical_rule_pack_id is null and m.rule_profile_version_id is null\n       and (m.message_family=''CONTRL''\n        or (m.message_family=''APERAK'' and m.execution_context_snapshot ? ''prodatCommonHeaderNegativeWitnessId''))) then\n    raise exception ''ediel_outbox_rule_pack_snapshot_missing'' using errcode=''23514'';\n  end if;\n  new.rule_profile_key:=m.rule_profile_key;\n  new.rule_profile_version_id:=m.rule_profile_version_id;\n  new.rule_profile_version:=m.rule_profile_version;\n  new.rule_pack_checksum:=m.rule_pack_checksum;\n  new.rule_pack_snapshot:=m.rule_pack_snapshot;\n  return new;\nend; ","after":"fbd2f31eab36c81ea9e54cd863872a9b","expected":{"acl":"{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}","owner":"postgres","procost":100,"prorows":0,"language":"plpgsql","arguments":"","proconfig":["search_path=public, pg_temp"],"prosecdef":false,"proargmodes":null,"proargnames":null,"proisstrict":false,"proparallel":"u","provolatile":"v","return_type":"trigger","proleakproof":false,"identity_arguments":""}}],"dependencies":[{"signature":"gridex_ediel_common_header.witness_v1(public.ediel_messages)","body_md5":"edbd546f620c16586a1b1c4e72989659","body":"DECLARE w gridex_ediel_common_header.negative_witnesses%rowtype;r jsonb;current_route jsonb;t jsonb;BEGIN\n w:=gridex_ediel_common_header.witness_before_route_v1(m);\n SELECT route INTO r FROM gridex_ediel_common_header.negative_route_bindings WHERE witness_id=w.id;\n IF r IS NULL OR m.communication_route_id::text IS DISTINCT FROM r#>>''{route,id}'' OR m.route_profile_id::text IS DISTINCT FROM r#>>''{routeRuntime,route_profile_id}''\n  OR m.sender_email IS DISTINCT FROM r->>''senderEmail'' OR m.receiver_email IS DISTINCT FROM r->>''receiverEmail'' OR m.mailbox IS DISTINCT FROM r->>''mailbox''\n  OR m.sender_ediel_id IS DISTINCT FROM r->>''senderEdielId'' OR m.receiver_ediel_id IS DISTINCT FROM r->>''receiverEdielId''\n  OR coalesce(m.sender_sub_address,'''') IS DISTINCT FROM coalesce(r->>''senderSubAddress'','''') OR coalesce(m.receiver_sub_address,'''') IS DISTINCT FROM coalesce(r->>''receiverSubAddress'','''')\n  OR m.application_reference IS DISTINCT FROM r->>''applicationReference'' THEN RAISE EXCEPTION ''ediel_common_header_negative_route_binding_required'';END IF;\n t:=gridex_ediel_technical_ack.require_source_v1(w.company_id,w.source_message_id);PERFORM gridex_ediel_common_header.require_current_scope_v1(w.evidence);\n current_route:=gridex_ediel_technical_ack.select_configured_reply_route_v2(w.company_id,t,''APERAK'',r->>''senderEmail'',r->>''smtpHost'',(r->>''smtpPort'')::integer);\n IF current_route IS DISTINCT FROM r THEN RAISE EXCEPTION ''ediel_common_header_negative_current_route_required'';END IF;\n RETURN w;END "},{"signature":"gridex_unattributed_intake.is_birth_v1(public.ediel_messages,boolean)","body_md5":"2c63e83c331e9d77ed239390bd6c4c54","body":"\n SELECT EXISTS(SELECT FROM gridex_unattributed_intake.technical_births b WHERE b.source_message_id=m.id\n  AND (NOT pending OR b.birth_transaction=txid_current()) AND m.company_id IS NULL AND m.resolved_company_id IS NULL\n  AND m.direction=''inbound'' AND m.message_standard=''edifact'' AND m.message_family=b.message_family AND m.message_code=b.message_code\n  AND m.environment=b.environment AND m.message_received_at=b.received_at AND m.inbound_email_message_id=b.inbound_email_message_id\n  AND m.mailbox_message_id=b.inbound_email_message_id::text\n  AND gridex_unattributed_intake.sha_v1(m.raw_payload)=b.payload_hash\n  AND gridex_ediel_technical_ack.envelope(m.raw_payload)=b.physical_envelope\n  AND m.customer_id IS NULL AND m.site_id IS NULL AND m.metering_point_id IS NULL AND m.grid_owner_id IS NULL\n  AND m.party_id IS NULL AND m.party_address_id IS NULL AND m.resolved_grid_owner_id IS NULL AND m.resolved_counterparty_id IS NULL\n  AND m.operation_id IS NULL AND m.intent_id IS NULL AND m.source_operation_id IS NULL AND m.outbound_request_id IS NULL\n  AND m.switch_request_id IS NULL AND m.grid_owner_data_request_id IS NULL AND m.grid_owner_information_request_id IS NULL\n  AND m.partner_export_id IS NULL AND m.related_message_id IS NULL AND m.communication_route_id IS NULL\n  AND m.canonical_rule_pack_id IS NULL AND m.execution_context_snapshot=''{}''::jsonb)\n"},{"signature":"gridex_ediel_header_negative_birth.is_bound_v1(public.ediel_messages,boolean)","body_md5":"b94af5111e2e78fd94774a51fa3436c6","body":"\n SELECT EXISTS(SELECT FROM gridex_ediel_header_negative_birth.receipts r WHERE r.source_message_id=m.id AND r.company_id=m.company_id AND r.environment=m.environment AND r.actor_user_id=m.created_by\n  AND r.inbound_email_message_id=m.inbound_email_message_id AND r.inbound_email_message_id::text=m.mailbox_message_id AND r.source_received_at=m.message_received_at AND r.payload_sha256=encode(sha256(convert_to(m.raw_payload,''UTF8'')),''hex'')\n  AND m.direction=''inbound'' AND m.message_standard=''edifact'' AND m.message_family=''PRODAT'' AND m.resolved_company_id=m.company_id\n  AND m.message_code=r.source_facts->>''messageCode'' AND m.application_reference IS NOT DISTINCT FROM r.source_facts->>''applicationReference''\n  AND m.sender_ediel_id=r.source_facts->>''senderEdielId'' AND m.receiver_ediel_id=r.source_facts->>''receiverEdielId'' AND m.interchange_reference=r.source_facts->>''interchangeReference''\n  AND m.canonical_rule_pack_id IS NULL AND m.rule_profile_version_id IS NULL AND m.rule_profile_key IS NULL AND m.rule_profile_version IS NULL AND m.rule_pack_checksum IS NULL AND coalesce(m.rule_pack_snapshot,''{}'')=''{}''::jsonb\n  AND m.switch_request_id IS NULL AND m.grid_owner_data_request_id IS NULL AND m.partner_export_id IS NULL\n  AND m.customer_id IS NULL AND m.site_id IS NULL AND m.metering_point_id IS NULL AND m.grid_owner_id IS NULL AND m.outbound_request_id IS NULL AND m.related_message_id IS NULL\n  AND ((pending AND r.status=''pending'' AND r.creation_txid=txid_current()) OR(NOT pending AND r.status=''consumed'')))\n"},{"signature":"gridex_ediel_header_negative_birth.evidence_v1(public.ediel_messages)","body_md5":"fe257056ec265b97a044d7cd97e6ca26","body":"\nDECLARE e jsonb;\nBEGIN\n IF NOT(gridex_ediel_header_negative_birth.is_bound_v1(m,true) OR gridex_ediel_header_negative_birth.is_bound_v1(m,false)) THEN RETURN NULL;END IF;\n SELECT evidence INTO e FROM gridex_ediel_header_negative_birth.receipts WHERE source_message_id=m.id;RETURN e;\nEND "},{"signature":"public.ediel_is_qualified_retention_transition_v1(public.ediel_messages,public.ediel_messages)","body_md5":"c9e018c4b712ce1437af97287115069b","body":"\n SELECT oldrow.raw_payload IS NOT NULL AND newrow.raw_payload IS NULL AND newrow.parsed_payload=''{}''::jsonb AND newrow.validation_report=''{}''::jsonb AND coalesce(newrow.metadata,''{}'')=''{}''::jsonb\n AND (to_jsonb(oldrow)-ARRAY[''raw_payload'',''parsed_payload'',''validation_report'',''metadata'',''updated_at'']) IS NOT DISTINCT FROM (to_jsonb(newrow)-ARRAY[''raw_payload'',''parsed_payload'',''validation_report'',''metadata'',''updated_at''])\n AND EXISTS(SELECT FROM gridex_ediel_retention.blob_tombstones t WHERE t.retention_class=''received_ediel_message_content'' AND t.target_id=oldrow.id AND t.company_id=oldrow.company_id AND t.source_hash=encode(sha256(convert_to(oldrow.raw_payload,''UTF8'')),''hex'') AND t.public_content_hash=encode(sha256(convert_to(gridex_ediel_retention.public_content_v1(oldrow)::text,''UTF8'')),''hex''))\n"},{"signature":"public.gridex_actor_has_company_permission(uuid,uuid,text)","body":"\n  select (p_actor_user_id is not null AND EXISTS(SELECT FROM public.permissions catalog WHERE catalog.key=p_permission AND catalog.is_active) and p_company_id is not null\n  and exists(\n    select 1 from auth.users u\n    where u.id = p_actor_user_id and u.deleted_at is null\n      and (u.banned_until is null or u.banned_until <= clock_timestamp())\n  )\n  and (\n    exists(\n      select 1 from public.admin_users au\n      where au.user_id = p_actor_user_id\n        and coalesce(au.is_active, true)\n        and lower(coalesce(au.role, '''')) in (''super_admin'', ''superadmin'', ''platform_superadmin'')\n    )\n    or exists(\n      select 1\n      from public.user_roles ur left join public.roles r on r.id = ur.role_id\n      where ur.user_id = p_actor_user_id and ur.company_id is null\n        and coalesce(ur.status, ''active'') = ''active'' and coalesce(ur.is_active, true)\n        and lower(coalesce(ur.role, r.key, r.name, '''')) in (''super_admin'', ''superadmin'', ''platform_superadmin'')\n    )\n    or (\n      exists(\n        select 1 from public.company_memberships cm\n        join public.companies c on c.id = cm.company_id\n        where cm.user_id = p_actor_user_id and cm.company_id = p_company_id\n          and coalesce(cm.status, ''active'') = ''active'' and coalesce(cm.is_active, true)\n          and coalesce(c.is_active, true)\n          and coalesce(c.status, ''active'') not in (''archived'', ''suspended'', ''pending_deletion'', ''deleted'')\n      )\n      and p_permission = any(\n        public.gridex_get_user_permissions_in_company(p_actor_user_id, p_company_id)\n      )\n    )\n  )\n  ) and not exists(\n    select 1 from public.user_permissions d left join public.permissions p on p.id=d.permission_id\n    where d.user_id=p_actor_user_id and (d.company_id is null or d.company_id=p_company_id)\n      and d.is_active and d.status=''active'' and d.effect=''deny''\n      and coalesce(nullif(d.permission_key,''''),p.key)=p_permission\n  ) and not exists(\n    select 1 from public.user_permission_overrides d\n    where d.user_id=p_actor_user_id and (d.company_id is null or d.company_id=p_company_id)\n      and d.is_active and d.effect=''deny'' and d.permission_key=p_permission\n      and (d.valid_from is null or d.valid_from<=clock_timestamp()) and (d.valid_to is null or clock_timestamp()<d.valid_to)\n  )\n","body_md5":"02c126207b21142e0de62563a287ea1e"},{"signature":"gridex_ediel_wire_namespace.before_message_write()","body":"\nBEGIN\n IF TG_OP=''UPDATE'' AND (NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.environment IS DISTINCT FROM OLD.environment OR NEW.direction IS DISTINCT FROM OLD.direction)\n  AND EXISTS(SELECT FROM gridex_ediel_wire_namespace.coverage WHERE source_message_id=OLD.id) THEN RAISE EXCEPTION ''ediel_wire_reference_namespace_context_immutable''; END IF;\n PERFORM gridex_ediel_wire_namespace.reserve(NEW);\n RETURN NEW;\nEND ","body_md5":"34f9d97c05f1805f4a3bea96256aa7a6"},{"signature":"gridex_ediel_wire_namespace.immutable()","body":"\nBEGIN RAISE EXCEPTION ''ediel_wire_reference_reservation_immutable''; END ","body_md5":"e56df235ff9099e5bfc6172ad536d9ec"},{"signature":"gridex_unattributed_intake.guard_original_v1()","body":"\nDECLARE mail_id uuid;old_mail_id uuid;old_json jsonb;new_json jsonb;\nBEGIN\n IF TG_TABLE_NAME=''ediel_messages'' THEN\n  IF NOT EXISTS(SELECT FROM gridex_unattributed_intake.technical_births WHERE source_message_id=OLD.id) THEN\n   IF TG_OP=''DELETE'' THEN RETURN OLD;END IF;RETURN NEW;\n  END IF;\n  IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''ediel_technical_intake_original_immutable'';END IF;\n  IF OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;\n  old_json:=to_jsonb(OLD)-ARRAY[''status'',''validation_report'',''contrl_status'',''aperak_status'',''utilts_err_status'',''ack_outcome'',\n   ''syntax_check_status'',''functional_check_status'',''failure_reason'',''parsed_at'',''validated_at'',''acknowledged_at'',''failed_at'',\n   ''ack_due_at'',''updated_at'',''updated_by'',''tenant_resolution_status'',''business_match_status'',''ack_status'',''processing_status'',\n   ''backend_automation_status'',''backend_automation_reason'',''contrl_due_at'',''business_response_due_at'',''response_overdue_at''];\n  new_json:=to_jsonb(NEW)-ARRAY[''status'',''validation_report'',''contrl_status'',''aperak_status'',''utilts_err_status'',''ack_outcome'',\n   ''syntax_check_status'',''functional_check_status'',''failure_reason'',''parsed_at'',''validated_at'',''acknowledged_at'',''failed_at'',\n   ''ack_due_at'',''updated_at'',''updated_by'',''tenant_resolution_status'',''business_match_status'',''ack_status'',''processing_status'',\n   ''backend_automation_status'',''backend_automation_reason'',''contrl_due_at'',''business_response_due_at'',''response_overdue_at''];\n  IF old_json IS DISTINCT FROM new_json OR gridex_unattributed_intake.is_birth_v1(NEW) IS NOT TRUE THEN\n   RAISE EXCEPTION ''ediel_technical_intake_original_immutable'' USING ERRCODE=''23514'';END IF;\n ELSE\n  IF TG_TABLE_NAME=''inbound_email_messages'' THEN mail_id:=OLD.id;\n  ELSE\n   IF TG_OP<>''DELETE'' THEN mail_id:=NEW.inbound_email_message_id;END IF;\n   IF TG_OP<>''INSERT'' THEN old_mail_id:=OLD.inbound_email_message_id;END IF;\n  END IF;\n  IF EXISTS(SELECT FROM gridex_unattributed_intake.technical_births WHERE inbound_email_message_id IN(mail_id,old_mail_id)) THEN\n   IF TG_TABLE_NAME=''inbound_email_messages'' AND TG_OP=''UPDATE'' AND NEW.company_id IS NULL\n    AND gridex_unattributed_intake.raw_hash_v1(NEW)=gridex_unattributed_intake.raw_hash_v1(OLD) THEN RETURN NEW;END IF;\n   IF TG_TABLE_NAME=''inbound_ediel_parse_results'' AND TG_OP=''UPDATE''\n    AND gridex_unattributed_intake.parse_hash_v1(NEW)=gridex_unattributed_intake.parse_hash_v1(OLD) THEN RETURN NEW;END IF;\n   RAISE EXCEPTION ''ediel_technical_intake_custody_immutable'' USING ERRCODE=''23514'';\n  END IF;\n END IF;\n IF TG_OP=''DELETE'' THEN RETURN OLD;END IF;RETURN NEW;\nEND ","body_md5":"c81331d3c2547e3b12cccc137b9d4041"},{"signature":"gridex_unattributed_intake.immutable_v1()","body":" BEGIN\n RAISE EXCEPTION ''ediel_technical_intake_receipt_immutable'' USING ERRCODE=''23514'';END ","body_md5":"41e0af9e9739fa278954ee158306ba38"},{"signature":"gridex_ediel_technical_ack.immutable()","body":" BEGIN RAISE EXCEPTION ''ediel_technical_ack_basis_immutable'';END ","body_md5":"e589337a6d3e876d65e87075fffea3d1"},{"signature":"gridex_ediel_common_header.immutable()","body":"BEGIN RAISE EXCEPTION ''ediel_common_header_basis_immutable'';END","body_md5":"d200e73c3796c325038da595d54c4ac8"}],"dispatcher":{"signature":"public.gridex_require_outbound_reply_basis_v1(public.ediel_messages)","body_md5":"e53f0edcd41a01809569a0cc22657630","body":"\nDECLARE persisted public.ediel_messages%rowtype;\nBEGIN\n -- JWT subject/tenant read permission precede every private source read or lock.\n IF auth.role()=''authenticated'' AND (auth.uid() IS NULL OR m.company_id IS NULL OR public.gridex_actor_has_company_permission(auth.uid(),m.company_id,''communication.read'') IS NOT TRUE) THEN\n  RAISE EXCEPTION ''ediel_reply_source_scope_required'' USING ERRCODE=''42501'';\n END IF;\n IF auth.role()=''authenticated'' THEN\n  SELECT * INTO persisted FROM public.ediel_messages own WHERE own.id=m.id AND own.company_id=m.company_id;\n  IF NOT FOUND OR persisted IS DISTINCT FROM m